from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime
from enum import Enum
from typing import List, Optional, Dict, Any

from src.data.models import Bar


class SignalAction(str, Enum):
    BUY = "BUY"
    SELL = "SELL"
    EXIT = "EXIT"
    HOLD = "HOLD"

    def __str__(self) -> str:
        return self.value


@dataclass
class Signal:
    """Standardized trading signal generated by a strategy."""
    symbol: str
    action: SignalAction
    timestamp: datetime
    price: float
    confidence: float  # 0.0 to 1.0
    strategy_name: str
    indicators: Dict[str, Any] = field(default_factory=dict)
    reason: str = ""
    stop_loss: Optional[float] = None
    take_profit: Optional[float] = None
    quantity: int = 1

    def __post_init__(self):
        if not 0.0 <= self.confidence <= 1.0:
            raise ValueError(f"Confidence must be between 0.0 and 1.0, got {self.confidence}")
        if self.quantity < 1:
            raise ValueError(f"Quantity must be at least 1, got {self.quantity}")

    def to_dict(self) -> Dict[str, Any]:
        return {
            "symbol": self.symbol,
            "action": str(self.action),
            "timestamp": self.timestamp.isoformat() if self.timestamp else None,
            "price": self.price,
            "confidence": self.confidence,
            "strategy_name": self.strategy_name,
            "indicators": self.indicators,
            "reason": self.reason,
            "stop_loss": self.stop_loss,
            "take_profit": self.take_profit,
            "quantity": self.quantity,
        }


class Strategy(ABC):
    """Abstract base class for all trading strategies."""

    def __init__(self, name: str, parameters: Optional[Dict[str, Any]] = None):
        self.name = name
        self.parameters = parameters or {}

    @abstractmethod
    def generate_signals(self, bars: List[Bar]) -> List[Signal]:
        """Generate trading signals from a list of bars.

        Args:
            bars: Chronologically sorted list of OHLCV bars (oldest first)

        Returns:
            List of Signal objects. May be empty if no signals are generated.
        """
        pass

    def get_latest_signal(self, bars: List[Bar]) -> Optional[Signal]:
        """Get the most recent signal from the generated signal list.

        Args:
            bars: Chronologically sorted list of bars

        Returns:
            The latest Signal, or None if no signals exist
        """
        signals = self.generate_signals(bars)
        return signals[-1] if signals else None

    def get_latest_bars(self, bars: List[Bar], count: int) -> List[Bar]:
        """Extract the most recent N bars.

        Args:
            bars: Full bar list
            count: Number of bars to extract

        Returns:
            List of the most recent 'count' bars
        """
        return bars[-count:] if len(bars) >= count else bars

    def _calculate_confidence(
        self,
        primary_factor: float,
        secondary_factor: Optional[float] = None,
        tertiary_factor: Optional[float] = None,
    ) -> float:
        """Calculate weighted confidence score from 1-3 factors."""
        """Calculate weighted confidence score from 1-3 factors.

        Args:
            primary_factor: Main confidence factor (0.0 to 1.0)
            secondary_factor: Optional second factor
            tertiary_factor: Optional third factor

        Returns:
            Weighted average confidence (0.0 to 1.0)
        """
        factors = [primary_factor]
        if secondary_factor is not None:
            factors.append(secondary_factor)
        if tertiary_factor is not None:
            factors.append(tertiary_factor)

        return sum(factors) / len(factors)